// InstallSpec Install intent template (docs/04-install-spec.md §5). Any string value may carry template references — `{var:name}` (resolved from the target's `targets[].vars`), `{index}`, `{machine_id}`, `{serial}`, `{bmc_address}`, `{label:key}` — expanded per machine at submission; unrecognized `{...}` sequences stay literal, so shell `${...}` and JSON snippets pass through untouched. base64 script bodies are opaque and never templated. Resolution runs at submission per machine; a missing binding rejects the whole request (422 SCHEMA_UNRESOLVED_VAR), a malformed address after substitution rejects with SCHEMA_INVALID_ADDRESS.
type InstallSpec struct {
	Access *AccessSpec `json:"access,omitempty"`

	// Boot Boot carrier strategy (docs/06-install-pipeline.md §3). Absent → the server default (capabilities.boot_strategy_default).
	Boot     *BootSpec     `json:"boot,omitempty"`
	Identity *IdentitySpec `json:"identity,omitempty"`
	Image    struct {
		// Checksum e.g. `sha256:9f86d0...`. With id, defaults to the registration's digest; a conflicting explicit checksum is rejected at submit.
		Checksum *string `json:"checksum,omitempty"`

		// Distro Explicitly declared (no implicit detection), e.g. rocky9.
		// The special key `dd` selects the image-direct-write pathway
		// (docs/09「镜像直写通路」): the spec's image is a pre-built
		// whole-disk image streamed onto exactly one target disk by the
		// agent initramfs — both boot carriers (virtual_media via the
		// alpine standard ISO mounted by the BMC, and PXE via the
		// netboot tarball); checksum required; the image owns the
		// partition table, so partitions/lvm/raid/identity/network
		// intent is honestly rejected with 422.
		Distro string `json:"distro"`

		// Format dd pathway only: the image's compression. raw = uncompressed;
		// raw.gz = gzip (busybox gunzip inline — the runtime decompresses
		// on the fly while streaming to disk; the RECOMMENDED delivery —
		// zero extra dependencies); raw.xz = xz (needs the alpine
		// extended pool staged for the apk xz package — the engine gates
		// it at prepare). The checksum is always the UNCOMPRESSED
		// image's sha256 (the stream that hits the disk is verified
		// byte-for-byte). Other distros reject the field.
		Format *InstallSpecImageFormat `json:"format,omitempty"`

		// Id Registered image id from the artifact library (POST /images). The engine resolves it to the checksum-gated local cache file at submit time and snapshots the resolution into the job spec — later registration deletes do not affect submitted jobs. Mutually exclusive with source.
		Id *string `json:"id,omitempty"`

		// SizeBytes dd pathway only: the image's byte span (read-back verification
		// spans exactly these bytes after the write). The artifact-library
		// resolution carries it automatically from the registration;
		// bare-inline specs should declare it explicitly — without it the
		// runtime falls back to stream-hash-only verification. Other
		// distros reject the field.
		SizeBytes *int64 `json:"size_bytes,omitempty"`

		// Source Installer image URL (file, http(s) or nfs URI reachable from the engine host). Mutually exclusive with id — exactly one of the two is required.
		Source *string `json:"source,omitempty"`

		// WindowsImageName Windows only: explicit /IMAGE/NAME inside install.wim for the
		// unattend's image selection, overriding the driver default
		// ("Windows Server <year> SERVERSTANDARDCORE" — Standard Core,
		// docs/compat/distros.md §windows 镜像契约). For non-standard
		// media (custom-built, cloud-exported, Essentials) whose image
		// names carry a different form. Matched case-insensitively by
		// substring, same as the default. Ignored by other distros.
		WindowsImageName *string `json:"windows_image_name,omitempty"`
	} `json:"image"`
	Network *[]NetworkInterface `json:"network,omitempty"`

	// PackageSource Declared package repositories (docs/04-install-spec.md §5.5) — written into the installed system's package manager config by the dialect renderer; windows rejects the block at render time.
	PackageSource *PackageSourceSpec `json:"package_source,omitempty"`
	Scripts       *[]ScriptSpec      `json:"scripts,omitempty"`
	Storage       *StorageSpec       `json:"storage,omitempty"`
}

// InstallSpecImageFormat dd pathway only: the image's compression. raw = uncompressed;
// raw.gz = gzip (busybox gunzip inline — the runtime decompresses
// on the fly while streaming to disk; the RECOMMENDED delivery —
// zero extra dependencies); raw.xz = xz (needs the alpine
// extended pool staged for the apk xz package — the engine gates
