func (t ActionRequest) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t ActionRequest) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "boot_rescue":
		return t.AsActionBootRescue()
	case "cycle":
		return t.AsActionCycle()
	case "discover":
		return t.AsActionDiscover()
	case "eject_media":
		return t.AsActionEjectMedia()
	case "erase_drives":
		return t.AsActionEraseDrives()
	case "hard_reboot":
		return t.AsActionHardReboot()
	case "mount_media":
		return t.AsActionMountMedia()
	case "power_off":
		return t.AsActionPowerOff()
	case "power_on":
		return t.AsActionPowerOn()
	case "reboot":
		return t.AsActionReboot()
	case "set_bios_attributes":
		return t.AsActionSetBiosAttributes()
	case "set_boot_device":
		return t.AsActionSetBootDevice()
	case "soft_off":
		return t.AsActionSoftOff()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

